import math

def is_prime(n: int) -> bool:
    """Check if n is a prime number."""

    # Handle edge cases
    if n <= 1:
        return False

    # Check for factors up to sqrt(n)
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False

    return True

