def fizzbuzz(n: int) -> list[str]:
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        elif i % 3 != 0 and i % 5 != 0:
            result.append(str(i))
    return result

# Test cases
assert fizzbuzz(5) == ['1', '2', 'Fizz', '4', 'Buzz']
assert fizzbuzz(15)[-1] == 'Fizz'
assert fizzbuzz(0) == []
assert len(fizzbuzz(30)) == 30

import math

def celsius_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit, rounded to one decimal place."""

    f = (c * 9/5) + 32

    # Round to one decimal place
    return round(f, 1)

